  function logoChoice(name,choices,selected){return `<div class="brand-choice">${choices.map((x,i)=>`<label><input type="radio" name="${name}" value="${esc(x.id)}" ${x.id===selected?'checked':''}><span>${logo(x.icon,x.id)}<strong>${esc(x.label||x.id)}</strong></span></label>`).join('')}</div>`;}
  function methodsChoice(selected=''){const methods=availableMethods(),chosen=methods.some(x=>x.id===selected)?selected:methods[0]?.id;return [...new Set(methods.map(m=>m.group))].map(group=>`<div class="choice-group"><div class="section-title">${group}</div>${logoChoice('provider',methods.filter(x=>x.group===group),chosen)}</div>`).join('');}
  const accountOptionsFor=(clientId,selected='')=>data.accounts.filter(a=>a.clientId===clientId).map(a=>`<option value="${esc(a.id)}" ${a.id===selected?'selected':''}>${esc(a.name)} · ${esc(platform(a.platform).label)}</option>`).join('');
  function updatePaymentAmount(){
    const form=$('#record-form');if(form?.dataset.type!=='payment')return;
    const a=form.elements.purpose.value==='account'?account(form.elements.accountId.value):null;
    const due=a?Math.max(0,Number(a.workflow?.sellingPrice||0)-sum(accountOrderPayments(a.id).filter(p=>p.status!=='Rejected'),'amountUsd')):0;
    form.elements.amount.value=form.elements.currency.value==='USD'&&due>0?Number(due.toFixed(2)):'';
    form.elements.amountUsd.value=due>0?Number(due.toFixed(2)):'';
  }
  function updatePaymentAccountSelect(){const form=$('#record-form');if(form?.dataset.type!=='payment')return;const clientId=form.elements.clientId.value,select=$('#form-payment-account'),previous=select.value,options=accountOptionsFor(clientId,previous);select.innerHTML=options||'<option value="">No account for this client yet</option>';const purpose=$('#form-payment-purpose');if(!options&&purpose.value==='account')purpose.value='general';$('#payment-account-field').hidden=purpose.value!=='account';$('#payment-account-field').querySelector('select').required=purpose.value==='account';updatePaymentAmount();}
  function accountRequestFields(){return `<div class="field full"><span>Platforms and accounts *</span><div class="platform-request-grid">${Object.entries(PLATFORM).map(([key,item])=>`<div class="platform-request"><label class="platform-request-title"><input type="checkbox" name="platformSelection" value="${esc(key)}">${logo(item.icon,key)}<strong>${esc(item.label)}</strong></label><div class="platform-request-fields" hidden><label class="field"><span>Number of accounts</span><input name="count_${key}" type="number" min="1" max="50" step="1" value="1"></label><label class="field"><span>Fee for this client (%)</span><input name="fee_${key}" type="number" min="0" max="100" step="0.01" value="${clientPricing($('#record-form')?.elements?.clientId?.value||data.clients[0]?.id,key,'Europe').fee}"></label>${['Meta','Google'].includes(key)?`<label class="field"><span>Account origin</span><select name="region_${key}"><option>Europe</option><option>China</option></select></label>`:''}<div class="account-items field full" data-platform="${key}"></div></div></div>`).join('')}</div><span class="hint">Prices and fees come from this client’s pricing. You can adjust them for this request. Add the account ID after setup.</span></div>`;}
  function updateAccountItems(platformName){const form=$('#record-form');if(form?.dataset.type!=='account')return;const box=form.querySelector(`.account-items[data-platform="${platformName}"]`),count=Math.min(50,Math.max(1,Number(form.elements[`count_${platformName}`]?.value)||1));if(!box)return;const remembered=new Map([...box.querySelectorAll('input,textarea')].map(x=>[x.name,x.value]));box.innerHTML=Array.from({length:count},(_,i)=>`<div class="account-item"><div class="section-title">${esc(platformName)} account ${i+1}</div><div class="form-grid">${field('BM / Business ID',`item_bm_${platformName}_${i}`,remembered.get(`item_bm_${platformName}_${i}`)||'','placeholder="Separate from ad account ID"')}${field('Selling price (USD)',`item_price_${platformName}_${i}`,remembered.get(`item_price_${platformName}_${i}`)??clientPricing(form.elements.clientId.value,platformName,form.elements[`region_${platformName}`]?.value||'').price,'type="number" min="0" step="0.01"')}${field('Account name (optional)',`item_name_${platformName}_${i}`,remembered.get(`item_name_${platformName}_${i}`)||'','placeholder="Generated if empty"')}${platformName==='Meta'?`<label class="field"><span>Facebook Pages required</span><input name="item_pageCount_${platformName}_${i}" type="number" min="0" max="50" step="1" value="${esc(remembered.get(`item_pageCount_${platformName}_${i}`)||'0')}"></label><label class="field full"><span>Facebook Page links (one per line)</span><textarea name="item_pages_${platformName}_${i}" rows="2" placeholder="https://facebook.com/...">${esc(remembered.get(`item_pages_${platformName}_${i}`)||'')}</textarea></label>`:''}</div></div>`).join('');}
