    if(type==='manager'){const m=data.managers.find(x=>x.id===recordId)||{};modal(recordId?'Edit manager':'Add manager',`<input type="hidden" name="id" value="${esc(recordId)}"><div class="form-grid">${field('Manager name *','name',m.name||'','required')}${field('Phone','phone',m.phone||'')}${field('Email','email',m.email||'','type="email"')}</div>`,'manager');}
    if(type==='income'){const x=data.agencyIncome.find(y=>y.id===recordId)||{};modal(recordId?'Edit agency income':'Add agency income',`<input type="hidden" name="id" value="${esc(recordId)}"><div class="form-grid">${field('Date received *','date',x.date||dayKey(iso()),'type="date" required')}${select('Income category *','category',INCOME_CATEGORIES,x.category||INCOME_CATEGORIES[0])}${field('Amount received *','amount',x.amount||'','type="number" min="0.01" step="0.01" required')}${select('Currency','currency',['USD','MAD','EUR','GBP'],x.currency||'USD')}${field('USD equivalent *','amountUsd',x.amountUsd||'','type="number" min="0.01" step="0.01" required')}<label class="field"><span>Platform (optional)</span><select name="platform"><option value="">No platform</option>${Object.entries(PLATFORM).map(([key,item])=>`<option value="${key}" ${x.platform===key?'selected':''}>${esc(item.label)}</option>`).join('')}</select></label>${field('Who paid / source *','source',x.source||'','required')}${field('Description','description',x.description||'')}</div><p class="note below">Add manual revenue here. Completed top-up fees and verified account sales appear automatically, so do not enter them twice.</p>`,'income');}
