  const SIDEBAR_KEY='adsolution-sidebar-collapsed';
  function applySidebarState(collapsed){$('.app').classList.toggle('sidebar-collapsed',collapsed);$('#menu-button').setAttribute('aria-expanded',String(!collapsed));$('#menu-button').setAttribute('aria-label',collapsed?'Expand sidebar':'Collapse sidebar');try{localStorage.setItem(SIDEBAR_KEY,collapsed?'1':'0');}catch{}}
