  function applyTheme(theme){document.documentElement.dataset.theme=theme;const dark=theme==='dark';$('#theme-toggle').setAttribute('aria-pressed',String(dark));$('#theme-toggle').setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');$('#theme-toggle .theme-icon use').setAttribute('href',dark?'/icons/ui.svg#sun':'/icons/ui.svg#moon');try{localStorage.setItem(THEME_KEY,theme);}catch{}}
